#!/usr/bin/env node
// suppressions-only-shrink.mjs — the lint ratchet, and it turns only one way.
//
//   node .github/scripts/suppressions-only-shrink.mjs [--base-absent] <current.json> <base.json>
//
// Exit 0  no file/rule pair is suppressed that was not suppressed before, and none suppresses more.
// Exit 1  a pair is new, or its count grew. The message names every one.
// Exit 2  a file could not be read or parsed. A check that cannot check must not pass.
//
// WHY: `eslint-suppressions.json` is what lets `complexity` and `max-lines-per-function` be ON for
// `src/**` while 615 violations that predate the decision stay recorded rather than forgiven. But a
// suppressions file is regenerated by a command, so without this it is simply a place to put a new
// violation: write the code, run the generator, commit both, and lint is green.
//
// A COUNT IS NOT ENOUGH, and a gate reviewer showed exactly how it fails: fix one old violation, add
// one new, regenerate — the total FALLS while new code is suppressed. So the comparison is per
// file and per rule, and it refuses a pair that is new as well as a pair that grew.
//
// WHAT THIS CANNOT SEE, said plainly because a guard that oversells itself is worse than none: the
// suppressions format records a COUNT per file per rule, not the identity of each violation. So
// fixing one violation in a file and adding a different one of the same rule in that same file
// leaves the count equal and passes here. Two things narrow it. ESLint refuses a suppression that
// no longer corresponds to a real violation — measured: fabricating one makes `eslint src` exit 2
// with "There are suppressions left that do not occur anymore" — so entries cannot be invented. And
// every file that gains a violation it did not have, or a second rule, or a higher count, is
// refused here. What is left is one violation traded for another inside one already-listed file and
// rule, which is visible in the diff of that file.
//
// THE BASE REVISION is the same problem `baseline-only-grows.mjs` solves and the same answer: a
// shallow CI checkout has no `origin/main`, and once something has landed on main, main compares
// equal to itself. CI pins `github.event.pull_request.base.sha`. A base with no suppressions file is
// a PASS — the commit that introduces one has nothing to compare against.

import * as fs from 'node:fs';

/**
 * Whether this is a suppressions file at all.
 *
 * <p>ESLint's shape is `{ "<file>": { "<rule>": { "count": <number> } } }`. Valid JSON is not a valid
 * suppressions file, and the two answers are different exit codes: `null`, `[]`, `42` and
 * `{"a": 1}` all parse, and reporting any of them as "a violation was added" would be a specific and
 * wrong accusation.</p>
 */
export function isSuppressions(value) {
  return typeof value === 'object'
    && value !== null
    && !Array.isArray(value)
    && Object.values(value).every((rules) => typeof rules === 'object'
      && rules !== null
      && !Array.isArray(rules)
      && Object.values(rules).every((entry) => typeof entry === 'object'
        && entry !== null
        && !Array.isArray(entry)
        && typeof entry.count === 'number'));
}

/** How many violations a file/rule pair suppresses, or 0 when it suppresses none. */
function countOf(where, file, rule) {
  return where[file]?.[rule]?.count ?? 0;
}

/**
 * Every file/rule pair the current file suppresses MORE of than the base did.
 *
 * <p>New pairs and grown pairs are the same answer, deliberately: both mean code that the rules now
 * forbid has been added and hidden. The message distinguishes them so a person can see which.</p>
 */
export function added(base, current) {
  const grew = [];

  for (const [file, rules] of Object.entries(current)) {
    for (const rule of Object.keys(rules)) {
      const was = countOf(base, file, rule);
      const now = countOf(current, file, rule);
      if (now > was) {
        grew.push({ file, rule, was, now });
      }
    }
  }

  return grew;
}

function read(path) {
  try {
    return JSON.parse(fs.readFileSync(path, 'utf8'));
  } catch (cause) {
    console.error(`suppressions-only-shrink: cannot read ${path}: ${cause.message}`);
    process.exit(2);
  }
}

const argv = process.argv.slice(2);
const baseAbsent = argv.includes('--base-absent');
const paths = argv.filter((one) => one !== '--base-absent');

// COUNTED, not checked for undefined. Sonar reads a destructured short array as never undefined
// and called the old check always-false; it was wrong about the runtime and right about the
// expression, and looking at why found the real hole: with THREE paths the script took the first
// two and compared a pair nobody asked about. Counting says what is meant in every reading.
if (paths.length !== 2) {
  console.error('usage: suppressions-only-shrink.mjs [--base-absent] <current.json> <base.json>');
  process.exit(2);
}

const [currentPath, basePath] = paths;

const current = read(currentPath);
if (!isSuppressions(current)) {
  console.error('suppressions-only-shrink: not an ESLint suppressions file — refusing to guess');
  process.exit(2);
}

// A base that carries no suppressions file has NOTHING to compare against, and that is a PASS
// rather than "everything in the current file is new". Comparing against an empty object would
// refuse the very commit that introduces the file, and every branch taken from before it existed.
// Caught by this script’s own test, which is the only reason it is right.
if (baseAbsent) {
  console.log('suppressions-only-shrink: OK — the base carries no suppressions file.');
  process.exit(0);
}

const base = read(basePath);
if (!isSuppressions(base)) {
  console.error('suppressions-only-shrink: the base is not a suppressions file — refusing to guess');
  process.exit(2);
}

const grew = added(base, current);
if (grew.length === 0) {
  const files = Object.keys(current).length;
  console.log(`suppressions-only-shrink: OK — nothing new is suppressed (${files} file(s) recorded).`);
  process.exit(0);
}

console.error('suppressions-only-shrink: new lint violations are being SUPPRESSED rather than fixed.');
console.error('');
for (const { file, rule, was, now } of grew) {
  console.error(was === 0
    ? `  ${file}  ${rule}: ${now} newly suppressed`
    : `  ${file}  ${rule}: ${was} -> ${now}`);
}
console.error('');
console.error('These rules are ON for new code. Fix the violation, or say in review why this file');
console.error('must grow its suppression — the file is regenerated with:');
console.error('  npx eslint src --suppress-rule complexity --suppress-rule max-lines-per-function');
process.exit(1);
